#ifndef ZOVUTILS_DIRCOLORS_BACKEND_H
#define ZOVUTILS_DIRCOLORS_BACKEND_H
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <ctype.h>
static inline char*zov_dc_trim(char*s){while(isspace((unsigned char)*s))s++;size_t n=strlen(s);while(n&&isspace((unsigned char)s[n-1]))s[--n]=0;return s;}
static inline const char*zov_dc_key(const char*s){if(!strcmp(s,"NORMAL"))return"no";if(!strcmp(s,"FILE"))return"fi";if(!strcmp(s,"DIR"))return"di";if(!strcmp(s,"LINK"))return"ln";if(!strcmp(s,"MULTIHARDLINK"))return"mh";if(!strcmp(s,"FIFO"))return"pi";if(!strcmp(s,"SOCK"))return"so";if(!strcmp(s,"DOOR"))return"do";if(!strcmp(s,"BLK"))return"bd";if(!strcmp(s,"CHR"))return"cd";if(!strcmp(s,"ORPHAN"))return"or";if(!strcmp(s,"MISSING"))return"mi";if(!strcmp(s,"SETUID"))return"su";if(!strcmp(s,"SETGID"))return"sg";if(!strcmp(s,"CAPABILITY"))return"ca";if(!strcmp(s,"STICKY"))return"st";if(!strcmp(s,"OTHER_WRITABLE"))return"ow";if(!strcmp(s,"STICKY_OTHER_WRITABLE"))return"tw";if(!strcmp(s,"EXEC"))return"ex";if(s[0]=='*')return s;return NULL;}
static inline int zov_dircolors_run(int argc,char**argv){int csh=0,printdb=0;const char*file=NULL;for(int i=0;i<argc;i++){const char*a=argv[i];if(!strcmp(a,"--help")){puts("Usage: dircolors [OPTION]... [FILE]\nOutput commands to set the LS_COLORS environment variable.\n  -b, --sh, --bourne-shell  output Bourne shell code\n  -c, --csh, --c-shell      output C shell code\n      --print-database      output the default color database\n      --help                display this help and exit\n      --version             output version information and exit");return 0;}if(!strcmp(a,"--version")){puts("dircolors (zovutils) 0.10.0");return 0;}if(!strcmp(a,"-c")||!strcmp(a,"--csh")||!strcmp(a,"--c-shell")){csh=1;continue;}if(!strcmp(a,"-b")||!strcmp(a,"--sh")||!strcmp(a,"--bourne-shell")){csh=0;continue;}if(!strcmp(a,"--print-database")){printdb=1;continue;}if(a[0]=='-'&&strcmp(a,"-")){fprintf(stderr,"dircolors: unrecognized option '%s'\nTry 'dircolors --help' for more information.\n",a);return 1;}if(file){fprintf(stderr,"dircolors: extra operand '%s'\nTry 'dircolors --help' for more information.\n",a);return 1;}file=a;}if(printdb){puts("# Configuration file for dircolors\nTERM xterm\nDIR 01;34\nLINK 01;36\nFIFO 40;33\nSOCK 01;35\nBLK 40;33;01\nCHR 40;33;01\nORPHAN 40;31;01\nEXEC 01;32");return 0;}char*colors=(char*)calloc(65536,1);if(!colors)return 1;size_t used=0;FILE*f=file?fopen(file,"r"):NULL;if(file&&!f){fprintf(stderr,"dircolors: %s: %s\n",file,strerror(errno));free(colors);return 1;}if(f){char line[4096];while(fgets(line,sizeof line,f)){char*p=zov_dc_trim(line);if(!*p||*p=='#')continue;char*key=p;while(*p&&!isspace((unsigned char)*p))p++;if(!*p)continue;*p++=0;char*value=zov_dc_trim(p);const char*mapped=zov_dc_key(key);if(!mapped||!*value)continue;size_t a=strlen(mapped),b=strlen(value);if(used+a+b+3>=65536)break;if(used)colors[used++]=':';memcpy(colors+used,mapped,a);used+=a;colors[used++]='=';memcpy(colors+used,value,b);used+=b;colors[used]=0;}fclose(f);}if(used)colors[used++]=':';if(csh)printf("setenv LS_COLORS '%s'\n",colors);else printf("LS_COLORS='%s';\nexport LS_COLORS\n",colors);free(colors);return 0;}
#endif
